 const origin = "http://localhost:8787";
+const issuer = `${origin}/api/auth`;
+const resourceIdentifier = `${origin}/api`;
+const resourceScopes = ["openid", "profile", "email", "api:read"];
+
+type TokenResponse = {
+  access_token: string;
+  expires_at: number;
+  expires_in: number;
+  id_token?: string;
+  scope: string;
+  token_type: string;
+};
+
+type JwtKeySet = { keys: JsonWebKey[] };
